window.homepageTranslations={en:{attrs:{powerBi:"Power BI icon",excel:"Excel icon",sql:"SQL icon",azure:"Azure icon",python:"Python icon",fabric:"Fabric icon",pulse:"A preview of the DataArcus Pulse sales CRM dashboard",fintech:"A preview of the Fintech Portfolio Risk dashboard",repeatiq:"A preview of the RepeatIQ Commerce Analytics dashboard",founder:"A photo of Abdelrahman M., Founder of DataArcus",googleCert:"Google Data Analytics Professional Certificate",msCert:"Microsoft Certified: Data Analyst Associate"},meta:{title:"DataArcus - Power BI, Checked and Made for the Gulf",description:"Check your Power BI model free, add Ramadan, Eid and Hijri calendars with Gulf weekends, and get report design and model audits from an analyst in Dubai.",keywords:"Power BI consultant, data modeling, DAX, business intelligence dashboards, MENA, CRM analytics, Power BI specialist",author:"DataArcus","og:type":"website","og:title":"DataArcus - Power BI, Checked and Made for the Gulf","og:description":"Check your Power BI model free, add Ramadan, Eid and Hijri calendars with Gulf weekends, and get report design and model audits from an analyst in Dubai.","og:url":"https://dataarcus.com/","og:site_name":"DataArcus","og:image":"https://dataarcus.com/assets/img/og/home.jpg","og:image:alt":"The DataArcus logo showing animated data bars and the brand name.","og:locale":"en_US","twitter:card":"summary_large_image","twitter:title":"DataArcus - Power BI, Checked and Made for the Gulf","twitter:description":"Check your Power BI model free, add Ramadan, Eid and Hijri calendars with Gulf weekends, and get report design and model audits from an analyst in Dubai.","twitter:image":"https://dataarcus.com/assets/img/og/home.jpg","twitter:image:alt":"The DataArcus logo showing animated data bars and the brand name.",canonical:"https://dataarcus.com/"},hero:{title:"Power BI reports checked in Power BI, not just generated",subtitle:"AI can now build a Power BI report in minutes. DataArcus works beside Microsoft's tools to check yours and fit it to the Gulf: a free model health check, Ramadan, Eid and Hijri calendars with each country's weekend, and Arabic reports laid out right to left (in <a href='/power-bi-mcp/' class='text-accent'>private beta</a>).",buttonWork:"Explore My Work",buttonDiscuss:"Book a Free Data Clarity Call",buttonAgent:"Try the AI agent (beta)",badgeSecurity:"Enterprise Security",badgeTurnaround:"Fast Turnaround",badgeExcellence:"Committed to Excellence",commitmentTitle:"Our Commitment to Excellence",commitmentPoints:["Advanced DAX & Power Query Mastery","Unified Business Data Modeling","Enterprise Governance & Security","Custom Visual Development"],proofBadges:["Microsoft Certified Power BI Data Analyst","Every number validated against the source","Arabic & English"],proof:{live:"Production model",subtitle:"Sales CRM, anonymized",caption:"Three disconnected systems, one model, every lead resolved once and matched against the source.",link:"See the live dashboard"}},techStack:{label:"Tools I work with",powerbi:"Power BI",excel:"Excel",azure:"Azure",fabric:"Fabric"},services:{title:"Solutions Built Around Your Data, Not a Template",subtitle:"CRM, e-commerce, project tools or spreadsheets: whatever your business runs on, I turn it into a model your team can actually trust.",cards:[{title:"Executive & Operational Dashboards",desc:"A real-time, single view of your business, built the way every DataArcus model is: one validated source of truth instead of five reports that quietly disagree."},{title:"Reliable Data Modeling & Pipelines",desc:"Your dashboards are only as good as the model underneath them. I build clean, documented models validated against the source system before anything goes live."},{title:"Predictive & Trend Analysis",desc:"Beyond what happened: forecasting, cohort analysis, and pacing models that show you what's coming next, whether that's next month's sales pace or a lead about to go cold."},{title:"Governance & Security",desc:"Row-level security and PII-safe anonymization built into the model from day one, not bolted on after the fact."}],auditLink:'Getting ready for Copilot? <a href="services/copilot-readiness-audit.html" class="text-accent">See the fixed-price Copilot readiness audit</a>.'},portfolio:{title:"Solution Showcases",subtitle:"Explore my proof-of-concept dashboards, engineered to solve common business challenges. See what's possible for your data.",cardPulse:{badge:"SALES CRM",title:"DataArcus Pulse: CRM Intelligence",desc:"A production-grade sales CRM command center: leads, calls and call journeys resolved into one documented model with daily pacing targets."},cardFintech:{badge:"FINTECH & RISK",title:"Fintech Portfolio Risk Engine",desc:"A live early-warning system for 72 projects, analyzing budget, schedule, and delivery risk using Earned Value Management (EVM)."},cardRepeatiq:{badge:"E-COMMERCE & RETENTION",title:"RepeatIQ Commerce Analytics",desc:"A 5-page strategic suite maximizing Customer Lifetime Value (CLV) through cohort analysis, churn prediction, and risk modeling."},cardCfpb:{badge:"FINANCE & COMPLIANCE",title:"Consumer Financial Complaints",desc:"A 4-page showcase analyzing 7 years of U.S. consumer complaints, focusing on trends, company accountability, and regional fairness."},button:"View All Showcases"},about:{title:"Generating is easy. Checking is the work.",subtitle:"Generating a Power BI report with AI is now free and official. What still takes care is knowing that the numbers hold, that the model behind them is sound, and that Ramadan, Eid and the Gulf weekend are handled. DataArcus is built around that.",note:"Microsoft's <a href='https://learn.microsoft.com/power-bi/developer/agentic/power-bi-agentic-overview' class='text-accent' target='_blank' rel='noopener'>report-authoring skills</a> are free, but they run in an AI coding agent such as GitHub Copilot, on its own plan; <a href='https://learn.microsoft.com/power-bi/create-reports/copilot-introduction' class='text-accent' target='_blank' rel='noopener'>Copilot inside Power BI</a> needs a paid Fabric capacity (F2 or higher) or Power BI Premium (P1 or higher).",quote:'"My name is Abdelrahman M. I\'ve spent 2 years working in CRM and data-driven operations, and I got tired of waiting for someone else to build the reporting I actually needed, so I started building it myself in Power BI. DataArcus is where that work lives: real, production-grade models, not templates."',p1:"Behind DataArcus is one person, me, building every tool and checking every report myself. Alongside the free tools I take paid work: designing Power BI reports and auditing models, including a Copilot-readiness audit. You deal directly with the person doing the work, and what you see in the portfolio is what you get.",founder:"Abdelrahman M., Founder & Lead Data Architect",certification:{title:"Industry Certified",subtitle:"Data Analytics Professional",verified:"Verified by Google & Microsoft"},statsTitle:"The Track Record So Far",statsSubtitle:"Real numbers from real production models, not agency metrics.",stats:[{title:"Articles Published on the Blog"},{title:"Languages: English and Arabic"},{title:"End-to-End Dashboard Builds"},{title:"Free Power BI & Fabric Tools Published"},{title:"AI agent in private beta (8 tools)"}],ctaTitle:"Curious What This Could Look Like for Your Data?",ctaSubtitle:"No obligation. Tell me what you're working with, and I'll show you what's possible on a quick call.",ctaButton:"Book a Free Data Clarity Call"},process:{title:"How a Project Works",subtitle:"Three steps, no surprises.",steps:[{title:"Free Data Clarity Call",desc:"20 minutes on your data and the decisions you need to make. You get a straight answer on what's fixable, even if we never work together."},{title:"Build and Validate",desc:"I build the data model and dashboards, and check every number against your source system before you see a single chart."},{title:"Handover and Support",desc:"Your team gets the report, a walkthrough and documentation. Changes after launch are one message away, and you talk to the person who built it."}]},toolsStrip:{badge:"Free · No sign-up",title:"Free Power BI & Fabric Tools",subtitle:"Built from real client work. Use them on your own reports today.",button:"See all tools",cards:[{tag:"Build",title:"Theme & Layout Generator",desc:"Brand colors to a theme JSON, plus a matching page layout."},{tag:"Build",title:"DAX Calendar Generator",desc:"Date table with Hijri dates and Ramadan flags."},{tag:"Build",title:"DAX Measure Builder",desc:"YTD, YoY, rolling and running totals in one click."},{tag:"Check",title:"Model Health Check",desc:"Score your model: unused columns, slow DAX, broken visuals."},{tag:"Check",title:"Licensing Cost Calculator",desc:"Pro, PPU or Fabric for your team, in USD, AED or SAR."},{tag:"Learn",title:"DP-600 Practice Exam",desc:"220 Fabric questions, mock exams and case studies."},{tag:"Learn",title:"PL-300 Practice Exam",desc:"228 Power BI questions, mock exams and renewal prep."},{tag:"Build",title:"SVG KPI Designer",desc:"KPI cards and sparklines for Power BI, as one DAX measure."}]},latest:{title:"Latest from the Blog",subtitle:"Playbooks from real models: the patterns, the mistakes, and the fixes.",button:"All articles",posts:{gulfCalendar:{badge:"GULF CALENDAR",title:"A Gulf Calendar in Power BI: Hijri Dates, Ramadan, Eid and the Right Weekend",date:"October 3, 2026",excerpt:"Ramadan and Eid move, and the UAE changed its weekend in 2022. One DAX calendar with Hijri dates, announced Ramadan and Eid days, each country's weekend, and an Eid window measure.",button:"Read Playbook"},aiReady:{badge:"COPILOT & AI",title:"Is Your Power BI Model Ready for AI? A 7-Point Check",date:"October 2, 2026",excerpt:"Copilot, data agents and the new Power BI apps all answer from your semantic model. The 7 things to fix first, from names and descriptions to Prep data for AI.",button:"Read Playbook"},reportStyles:{badge:"REPORT DESIGN",title:"One Design Doesn’t Fit All: 7 Power BI Report Styles",date:"September 29, 2026",excerpt:"Executive, sales, finance, marketing, operations, HR and customer service reports each answer a different question. The 7 styles with example pages, and a 3-question quiz to pick yours.",button:"Read Playbook"},reportRedesign:{badge:"REPORT DESIGN",title:"Same Visuals, New Design: How We Redesigned a Power BI Report in 5 Minutes",date:"September 28, 2026",excerpt:"A leads report with the right visuals but loud colours and a messy layout. The five design changes that fixed it, and how to make them in 5 minutes with a free tool.",button:"Read Playbook"},modelHealth:{badge:"BEST PRACTICE",title:"We Ran a Health Check on a Microsoft Power BI Sample. It Scored 84.",date:"September 25, 2026",excerpt:"Microsoft's public COVID-19 sample, checked in under a second: a quarter of its columns unused, two bookmarks pointing at a deleted column and auto date/time left on. What we found and how to check yours.",button:"Read Playbook"},ramadanSales:{badge:"POWER BI",title:"Ramadan Sales in Power BI: Compare This Ramadan With Last Ramadan",date:"September 23, 2026",excerpt:"SAMEPERIODLASTYEAR compares March with March, but Ramadan moved 11 days. The Hijri calendar and the one DAX measure that line up every Ramadan day by day.",button:"Read Playbook"},licensingGuide:{badge:"STRATEGY",title:"Power BI Pro, Premium Per User or Fabric: Which License Do You Actually Need?",date:"September 23, 2026",excerpt:"One number decides your Power BI license: how many people only view reports. Current prices, the F64 break-even point and a worked example.",button:"Read Playbook"},journeyAttribution:{badge:"DATA ENGINEERING",title:"Resolve Once, Hydrate Many: A DAX Pattern for Lead Attribution",date:"September 1, 2026",excerpt:"Why matching the same lead five times produces disagreeing KPIs, and the single-resolution DAX pattern that matched every lead exactly before replacing scattered join logic.",button:"Read Playbook"}}},faq:{title:"Your Questions, Answered",subtitle:"Here are the answers to the questions I get asked most before a project starts.",items:[{q:"How does the free Data Clarity Call work?",a:"<strong>It's a focused 20-minute call, not a sales pitch.</strong> Bring whatever you've got (a messy spreadsheet, a CRM export, your current dashboard) and I'll walk through what's actually fixable and what a real model would look like. No build, no obligation, just a straight answer on whether this is worth pursuing."},{q:"What's the real ROI of a Power BI implementation?",a:'<strong>Here\'s a simple way to estimate it, not a guarantee.</strong> If your team spends 10 hours a week on manual reporting, that\'s roughly 500+ hours a year, and that\'s before counting the cost of decisions made late because the numbers weren\'t ready.<div class="mt-3"><div class="row g-3"><div class="col-sm-6"><div class="p-3 rounded" style="background: rgba(253, 121, 168, 0.1);"><strong>Before:</strong><br>• 10h/week manual reports<br>• Delayed decisions<br>• Data inconsistencies</div></div><div class="col-sm-6"><div class="p-3 rounded" style="background: rgba(0, 206, 201, 0.1);"><strong>After:</strong><br>• 30min/week monitoring<br>• Real-time insights<br>• Confident decisions</div></div></div></div>'},{q:"How do you handle our sensitive business data?",a:'<strong>On the discovery call, we talk through your data without you needing to hand anything over.</strong> If we move forward, I work within your existing Microsoft environment using row-level security, encrypted connections, and enterprise-grade governance.<div class="mt-3"><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>NDA signed before any data access</span></div><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>Data stays in your Microsoft tenant</span></div><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>Role-based access controls implemented</span></div><div class="d-flex align-items-start"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>Full audit trail of all activities</span></div></div>'},{q:"What if our data is a mess? Excel exports, legacy systems, manual processes?",a:'<strong>That\'s normal, and it\'s exactly the kind of problem I solve.</strong> I connect and clean data from CRMs, e-commerce platforms, ERPs, and spreadsheets into one reliable model.<div class="mt-3 p-3 rounded" style="background: rgba(108, 92, 231, 0.1);"><strong>I connect to:</strong> CRM systems, Shopify, WooCommerce, SQL databases, APIs, Excel files, and most other common business data sources.</div><p class="mt-3 mb-0"><em>"The messier your data, the bigger the transformation impact."</em></p>'},{q:"Will our team be able to use the dashboards?",a:'<strong>Absolutely. I build for your team\'s skill level and provide comprehensive training.</strong> Every project includes user training and documentation, plus ongoing support options.<div class="mt-3"><div class="row g-2 small"><div class="col-md-6"><strong class="text-accent">For End Users:</strong><br>• How to read dashboards<br>• Filtering and drilling down<br>• Export and sharing options</div><div class="col-md-6"><strong class="text-accent">For Admins:</strong><br>• Data refresh schedules<br>• User permissions<br>• Basic troubleshooting</div></div></div>'},{q:"Why work with an independent specialist instead of a large agency?",a:"<strong>You get direct access to the person actually building your model.</strong> No account manager relaying requests to a junior analyst. I built <a href='dashboards/dataarcus-pulse.html' class='text-accent'>DataArcus Pulse</a>, a production-grade sales CRM model, entirely myself, and that's the level of hands-on ownership every project gets.<div class=\"mt-3 p-3 rounded\" style=\"background: rgba(0, 212, 255, 0.1); border: 1px solid var(--accent);\">What you lose versus a big firm is overhead. What you gain is speed, direct communication, and someone personally accountable for every number in your dashboard.</div>"},{q:"What if we're not sure what we need?",a:"<strong>That's exactly what the free Data Clarity Call is for.</strong> Bring what you've got, and I'll help you figure out where the real opportunity is, even if that's not a full dashboard build yet. No commitment required."},{q:"Does the AI agent see my data?",a:"<strong>It reads your model's structure, not the rows in it.</strong> The agent's tools run on your own computer, in Claude Desktop: they read your model's structure (tables, columns, measures, formats), not the rows in it, and write a new report next to your model. Claude Desktop asks before every file it writes. More on the <a href='/power-bi-mcp/' class='text-accent'>beta page</a> and in <a href='https://github.com/Antnioo/DataArcus/blob/main/mcp/PRIVACY.md' class='text-accent' target='_blank' rel='noopener'>PRIVACY.md</a>."}]},finalCta:{title:"Ready to See Your Data in Action?",subtitle:"Book a free 20-minute Data Clarity Call. No obligation, just a straight look at what's possible with what you've got.",button:"Book Your Free Call"},contact:{title:"Start a Conversation About Your Data",subtitle:"Tell me about your business and the decisions you need better data for, and I'll walk you through what's possible on a free call.",form:{name:"Full Name *",email:"Business Email *",company:"Company",platform:"Data Source / Platform (Optional)",platformPlaceholder:"e.g., CRM system, Shopify, internal database...",details:"Project Details *",placeholder:"e.g., We use a CRM and a few spreadsheets. We need a single view of leads, conversion, and team performance...",button:"Book My Free Call",response:"Response within 1 working day"},checklist:{title:"What to bring to your Data Clarity Call",items:[{title:"One decision you want to make faster",desc:'For example: "Which campaigns bring buyers, not just leads?"'},{title:"Where your data lives today",desc:"CRM export, Excel sheets, Shopify, Google Sheets..."},{title:"Who reads the numbers",desc:"You, a manager, the sales team?"},{title:'What "better" looks like',desc:"A report you stop building by hand, a number you can finally trust"}]},timeline:{title:"How a typical project runs",items:[{label:"Discovery and data access",value:"Week 1"},{label:"Data model and measures",value:"Weeks 1-2"},{label:"Dashboard build",value:"Weeks 2-3"},{label:"Testing, training and handover",value:"Weeks 3-4"}],note:"Smaller jobs, like one report on clean data, can take a few days. You get a fixed timeline after the call."}}},ar:{attrs:{powerBi:"أيقونة Power BI",excel:"أيقونة Excel",sql:"أيقونة SQL",azure:"أيقونة Azure",python:"أيقونة Python",fabric:"أيقونة Fabric",pulse:"معاينة للوحة DataArcus Pulse لتحليلات CRM للمبيعات",fintech:"معاينة للوحة مخاطر محفظة مشاريع Fintech",repeatiq:"معاينة للوحة تحليلات التجارة RepeatIQ",founder:"صورة عبدالرحمن م.، مؤسس DataArcus",googleCert:"شهادة Google Data Analytics الاحترافية",msCert:"شهادة Microsoft Certified: Data Analyst Associate"},meta:{title:"داتا أركوس - Power BI مُتحقَّق منه ومهيّأ للخليج",description:"افحص نموذج Power BI مجانًا، وأضف تقويم رمضان والعيد والتاريخ الهجري مع عطلات الخليج، واطلب تصميم التقارير وتدقيق النماذج من محلل بيانات في دبي.",keywords:"استشاري Power BI, نمذجة البيانات, DAX, لوحات تحكم ذكاء الأعمال, الشرق الأوسط, تحليلات CRM, متخصص Power BI",author:"داتا أركوس","og:type":"website","og:title":"داتا أركوس - Power BI مُتحقَّق منه ومهيّأ للخليج","og:description":"افحص نموذج Power BI مجانًا، وأضف تقويم رمضان والعيد والتاريخ الهجري مع عطلات الخليج، واطلب تصميم التقارير وتدقيق النماذج من محلل بيانات في دبي.","og:url":"https://dataarcus.com/","og:site_name":"داتا أركوس","og:image":"https://dataarcus.com/assets/img/og/home.jpg","og:image:alt":"شعار داتا أركوس مع أعمدة بيانات متحركة واسم العلامة التجارية.","og:locale":"ar_EG","twitter:card":"summary_large_image","twitter:title":"داتا أركوس - Power BI مُتحقَّق منه ومهيّأ للخليج","twitter:description":"افحص نموذج Power BI مجانًا، وأضف تقويم رمضان والعيد والتاريخ الهجري مع عطلات الخليج، واطلب تصميم التقارير وتدقيق النماذج من محلل بيانات في دبي.","twitter:image":"https://dataarcus.com/assets/img/og/home.jpg","twitter:image:alt":"شعار داتا أركوس مع أعمدة بيانات متحركة واسم العلامة التجارية.",canonical:"https://dataarcus.com/"},hero:{title:"تقارير Power BI نتحقق منها في Power BI نفسه، ولا نكتفي بتوليدها",subtitle:"صار بإمكان الذكاء الاصطناعي بناء تقرير Power BI في دقائق. يعمل داتا أركوس إلى جانب أدوات Microsoft ليفحص تقريرك ويهيّئه لطبيعة العمل في الخليج: فحص مجاني لنموذج البيانات، وتقويم برمضان والعيد والتاريخ الهجري مع عطلة نهاية الأسبوع في كل دولة، وتقارير عربية مصمَّمة من اليمين إلى اليسار (في <a href='/power-bi-mcp/' class='text-accent'>تجربة خاصة</a>).",buttonWork:"استكشف أعمالي",buttonDiscuss:"احجز مكالمة وضوح بيانات مجانية",buttonAgent:"جرّب الوكيل الذكي (تجريبي)",badgeSecurity:"أمان على مستوى الشركات",badgeTurnaround:"تنفيذ سريع",badgeExcellence:"ملتزمون بالتميز",commitmentTitle:"التزامنا بالتميز",commitmentPoints:["إتقان متقدم للغات DAX و Power Query","نمذجة موحدة لبيانات الأعمال","حوكمة وأمان على مستوى الشركات","تطوير واجهات مرئية مخصصة"],proofBadges:["محلل بيانات Power BI معتمد من Microsoft","كل رقم مُطابق مع المصدر","العربية والإنجليزية"],proof:{live:"نموذج إنتاج حقيقي",subtitle:"نظام CRM للمبيعات، ببيانات مجهولة الهوية",caption:"ثلاثة أنظمة منفصلة، نموذج واحد، وكل عميل محتمل يُحل مرة واحدة ويُطابق مع المصدر.",link:"شاهد لوحة التحكم"}},techStack:{label:"أدوات أعمل بها",powerbi:"Power BI",excel:"Excel",azure:"Azure",fabric:"Fabric"},services:{title:"حلول مبنية حول بياناتك، لا قالب جاهز",subtitle:"أيًا كانت المنصة التي تعمل عليها شركتك، سواء CRM أو تجارة إلكترونية أو أدوات إدارة مشاريع أو جداول بيانات، أحوّلها إلى نموذج يمكن لفريقك الوثوق به فعليًا.",cards:[{title:"لوحات تحكم تنفيذية وتشغيلية",desc:"رؤية لحظية وموحدة لأعمالك، مبنية بنفس الطريقة التي يُبنى بها كل نموذج في داتا أركوس: مصدر حقيقة واحد تم التحقق منه بدلاً من خمسة تقارير تتعارض بصمت."},{title:"نمذجة بيانات وخطوط بيانات موثوقة",desc:"جودة لوحات تحكمك تعتمد على جودة النموذج تحتها. أبني نماذج نظيفة وموثقة تم التحقق منها مقابل النظام المصدر قبل إطلاق أي شيء."},{title:"التحليل التنبؤي والاتجاهات",desc:"ما وراء ما حدث: نماذج تنبؤ وتحليل دفعات ووتيرة تُظهر لك ما هو قادم، سواء كان ذلك وتيرة مبيعات الشهر القادم أو عميلاً محتملاً على وشك أن يبرد."},{title:"الحوكمة والأمان",desc:"أمان على مستوى الصف وإخفاء هوية آمن للبيانات الحساسة، مدمجان في النموذج منذ اليوم الأول، وليسا إضافة لاحقة."}],auditLink:'تستعد لـ Copilot؟ <a href="services/copilot-readiness-audit.html" class="text-accent">اطّلع على تدقيق الجاهزية لـ Copilot بسعر ثابت</a>.'},portfolio:{title:"نماذج الحلول",subtitle:"استكشف لوحات التحكم التجريبية التي بنيتها. شاهد ما هو ممكن لبياناتك.",cardPulse:{badge:"CRM للمبيعات",title:"داتا أركوس بالس: ذكاء إدارة علاقات العملاء",desc:"مركز قيادة CRM للمبيعات بمستوى الإنتاج: العملاء المحتملون والمكالمات ورحلات الاتصال في نموذج واحد موثّق مع أهداف وتيرة يومية."},cardFintech:{badge:"التكنولوجيا المالية والمخاطر",title:"محرك مخاطر محافظ التكنولوجيا المالية",desc:"نظام إنذار مبكر لـ 72 مشروعًا، يحلل الميزانية والجدول الزمني ومخاطر التسليم باستخدام إدارة القيمة المكتسبة (EVM)."},cardRepeatiq:{badge:"التجارة الإلكترونية والاحتفاظ بالعملاء",title:"تحليلات RepeatIQ للتجارة",desc:"جناح استراتيجي من 5 صفحات لتعظيم القيمة الدائمة للعميل من خلال تحليل الدفعات (Cohorts) والتنبؤ بالتسرب."},cardCfpb:{badge:"تحليلات مالية وامتثال",title:"تحليل شكاوى الخدمات المالية",desc:"نموذج من 4 صفحات يحلل 7 سنوات من شكاوى المستهلكين في الولايات المتحدة، مع التركيز على الاتجاهات ومساءلة الشركات."},button:"عرض كل النماذج"},about:{title:"توليد التقرير سهل، والتحقق منه هو العمل الحقيقي",subtitle:"أصبح توليد تقارير Power BI بالذكاء الاصطناعي مجانيًا، ومن Microsoft نفسها. ويبقى الأهم أن تعرف أن الأرقام صحيحة، وأن النموذج وراءها سليم، وأن رمضان والعيد وعطلة الخليج محسوبة كما يجب. وحول هذا بُني داتا أركوس.",note:"<a href='https://learn.microsoft.com/power-bi/developer/agentic/power-bi-agentic-overview' class='text-accent' target='_blank' rel='noopener'>مهارات Microsoft لكتابة التقارير</a> مجانية، لكنها تعمل داخل وكيل برمجة بالذكاء الاصطناعي مثل GitHub Copilot بخطة اشتراكه الخاصة، أما <a href='https://learn.microsoft.com/power-bi/create-reports/copilot-introduction' class='text-accent' target='_blank' rel='noopener'>Copilot داخل Power BI</a> فيحتاج إلى سعة Fabric مدفوعة (F2 أو أعلى) أو Power BI Premium ‏(P1 أو أعلى).",quote:'"اسمي عبد الرحمن م. أمضيت سنتين في العمل ضمن إدارة علاقات العملاء والعمليات القائمة على البيانات، ثم مللت من انتظار شخص آخر ليبني التقارير التي أحتاجها فعليًا، فبدأت ببنائها بنفسي في Power BI. داتا أركوس هي المكان الذي يعيش فيه هذا العمل: نماذج حقيقية بمستوى الإنتاج، لا قوالب جاهزة."',p1:"وراء داتا أركوس شخص واحد، هو أنا، أبني كل أداة وأراجع كل تقرير بنفسي. وإلى جانب الأدوات المجانية أقبل أعمالًا مدفوعة: تصميم تقارير Power BI وتدقيق النماذج، ومنها تدقيق الجاهزية لـ Copilot. تتعامل مباشرة مع من يقوم بالعمل، وما تراه في المعرض هو ما ستحصل عليه.",founder:"عبد الرحمن م.، المؤسس وكبير مهندسي البيانات",certification:{title:"شهادات معتمدة",subtitle:"محترف تحليل بيانات",verified:"موثق من Google و Microsoft"},statsTitle:"السجل حتى الآن",statsSubtitle:"أرقام حقيقية من نماذج إنتاج حقيقية، لا مقاييس وكالات مصطنعة.",stats:[{title:"مقالًا منشورًا في المدونة"},{title:"لغتان: العربية والإنجليزية"},{title:"لوحة تحكم متكاملة تم بناؤها"},{title:"أدوات Power BI و Fabric مجانية منشورة"},{title:"وكيل ذكاء اصطناعي في نسخة تجريبية خاصة (8 أدوات)"}],ctaTitle:"هل تتساءل كيف سيبدو هذا لبياناتك؟",ctaSubtitle:"بدون أي التزام. أخبرني بما تعمل عليه، وسأوضح لك ما هو ممكن في مكالمة سريعة.",ctaButton:"احجز مكالمة وضوح بيانات مجانية"},process:{title:"كيف يسير المشروع",subtitle:"ثلاث خطوات، بدون مفاجآت.",steps:[{title:"مكالمة وضوح البيانات المجانية",desc:"20 دقيقة حول بياناتك والقرارات التي تحتاج إلى اتخاذها. تحصل على إجابة واضحة عمّا يمكن إصلاحه، حتى لو لم نعمل معًا."},{title:"البناء والتحقق",desc:"أبني نموذج البيانات ولوحات التحكم، وأطابق كل رقم مع نظامك المصدر قبل أن ترى أي رسم بياني."},{title:"التسليم والدعم",desc:"يحصل فريقك على التقرير وشرح عملي وتوثيق كامل. أي تعديل بعد الإطلاق على بُعد رسالة واحدة، مع الشخص الذي بناه مباشرة."}]},toolsStrip:{badge:"مجانية · بدون تسجيل",title:"أدوات Power BI و Fabric مجانية",subtitle:"مبنية من عمل حقيقي مع العملاء. استخدمها في تقاريرك اليوم.",button:"عرض كل الأدوات",cards:[{tag:"ابنِ",title:"مولّد السمات والتخطيطات",desc:"حوّل ألوان علامتك إلى ملف سمة JSON مع تخطيط صفحة مطابق."},{tag:"ابنِ",title:"مولّد تقويم DAX",desc:"جدول تواريخ بالتاريخ الهجري وعلامات رمضان."},{tag:"ابنِ",title:"منشئ مقاييس DAX",desc:"مقاييس YTD و YoY والمتحركة والتراكمية بنقرة واحدة."},{tag:"افحص",title:"فحص صحة النموذج",desc:"قيّم نموذجك: أعمدة غير مستخدمة، DAX بطيء، مرئيات مكسورة."},{tag:"افحص",title:"حاسبة تكلفة التراخيص",desc:"Pro أم PPU أم Fabric لفريقك، بالدولار أو الدرهم أو الريال."},{tag:"تعلّم",title:"اختبار DP-600 التجريبي",desc:"220 سؤالًا عن Fabric واختبارات تجريبية ودراسات حالة."},{tag:"تعلّم",title:"اختبار PL-300 التجريبي",desc:"228 سؤالًا عن Power BI واختبارات تجريبية وتحضير للتجديد."},{tag:"ابنِ",title:"مصمم بطاقات KPI",desc:"بطاقات مؤشرات وخطوط اتجاه لـ Power BI في مقياس DAX واحد."}]},latest:{title:"أحدث المقالات",subtitle:"أدلة عملية من نماذج حقيقية: الأنماط والأخطاء والحلول.",button:"كل المقالات",posts:{gulfCalendar:{badge:"التقويم الخليجي",title:"تقويم خليجي في Power BI: التاريخ الهجري ورمضان والعيد والعطلة الصحيحة",date:"3 أكتوبر 2026",excerpt:"رمضان والعيد يتحركان، والإمارات غيّرت عطلتها في 2022. تقويم DAX واحد بالتاريخ الهجري، ومواعيد رمضان والعيد المعلنة، وعطلة كل دولة، ومقياس لفترة العيد.",button:"اقرأ الدليل"},aiReady:{badge:"Copilot والذكاء الاصطناعي",title:"هل نموذج Power BI جاهز للذكاء الاصطناعي؟ فحص من 7 نقاط",date:"2 أكتوبر 2026",excerpt:"Copilot ووكلاء البيانات وتطبيقات Power BI الجديدة كلها تجيب من نموذجك الدلالي. سبعة أمور تصلحها أولًا، من الأسماء والأوصاف إلى Prep data for AI.",button:"اقرأ الدليل"},reportStyles:{badge:"تصميم التقارير",title:"تصميم واحد لا يناسب الجميع: 7 أنماط لتقارير Power BI",date:"29 سبتمبر 2026",excerpt:"تقارير الإدارة والمبيعات والمالية والتسويق والعمليات والموارد البشرية وخدمة العملاء تجيب كل منها عن سؤال مختلف. الأنماط السبعة بصفحات أمثلة، واختبار من 3 أسئلة لاختيار نمطك.",button:"اقرأ الدليل"},reportRedesign:{badge:"تصميم التقارير",title:"نفس العناصر، تصميم جديد: كيف أعدنا تصميم تقرير Power BI في 5 دقائق",date:"28 سبتمبر 2026",excerpt:"تقرير عملاء محتملين بالعناصر الصحيحة لكن بألوان صاخبة وتخطيط فوضوي. خمسة تغييرات في التصميم أصلحته، وكيف تطبقها في 5 دقائق بأداة مجانية.",button:"اقرأ الدليل"},modelHealth:{badge:"أفضل الممارسات",title:"فحصنا صحة نموذج Power BI تجريبي من Microsoft. النتيجة: 84 من 100.",date:"25 سبتمبر 2026",excerpt:"نموذج COVID-19 التجريبي العام من Microsoft فُحص في أقل من ثانية: ربع الأعمدة غير مستخدمة، وإشارتان مرجعيتان تشيران إلى عمود محذوف، وخيار Auto date/time مفعّل. هذا ما وجدناه وكيف تفحص نموذجك.",button:"اقرأ الدليل"},ramadanSales:{badge:"Power BI",title:"مبيعات رمضان في Power BI: قارن رمضان هذا العام برمضان الماضي",date:"23 سبتمبر 2026",excerpt:"تقارن SAMEPERIODLASTYEAR مارس بمارس، لكن رمضان تحرّك 11 يومًا. التقويم الهجري ومقياس DAX الذي يطابق كل رمضان يومًا بيوم.",button:"اقرأ الدليل"},licensingGuide:{badge:"استراتيجية",title:"Power BI Pro أم Premium Per User أم Fabric: أي ترخيص تحتاجه فعلًا؟",date:"23 سبتمبر 2026",excerpt:"رقم واحد يحسم ترخيص Power BI: عدد من يشاهدون التقارير فقط. الأسعار الحالية ونقطة التعادل لـ F64 ومثال عملي.",button:"اقرأ الدليل"},journeyAttribution:{badge:"هندسة البيانات",title:"حلّ مرة واحدة، غذِّ كل مكان: نمط DAX لعزو العملاء المحتملين",date:"1 سبتمبر 2026",excerpt:"لماذا تُنتج مطابقة نفس العميل المحتمل خمس مرات مؤشرات أداء متضاربة، ونمط DAX الذي وثّق تطابق كل عميل محتمل قبل استبدال منطق الربط المتناثر.",button:"اقرأ الدليل"}}},faq:{title:"الأسئلة الشائعة",subtitle:"إليك إجابات الأسئلة التي أسمعها غالبًا قبل بدء أي مشروع.",items:[{q:"كيف تعمل مكالمة وضوح البيانات المجانية؟",a:"<strong>إنها مكالمة مركّزة مدتها 20 دقيقة، وليست عرضًا ترويجيًا.</strong> أحضر ما لديك (جدول بيانات فوضوي، تصدير من CRM، لوحة تحكمك الحالية) وسأستعرض معك ما يمكن إصلاحه فعليًا وكيف سيبدو نموذج حقيقي. بدون بناء، بدون التزام، فقط إجابة صريحة حول ما إذا كان الأمر يستحق المتابعة."},{q:"ما هو العائد الحقيقي على الاستثمار (ROI) من تطبيق Power BI؟",a:'<strong>إليك طريقة بسيطة لتقديره، وليست ضمانًا.</strong> إذا كان فريقك يقضي 10 ساعات أسبوعيًا في إعداد التقارير اليدوية، فهذا يعني أكثر من 500 ساعة سنويًا، وهذا قبل احتساب تكلفة القرارات المتأخرة بسبب عدم جاهزية الأرقام.<div class="mt-3"><div class="row g-3"><div class="col-sm-6"><div class="p-3 rounded" style="background: rgba(253, 121, 168, 0.1);"><strong>قبل:</strong><br>• ١٠ ساعات/أسبوع تقارير يدوية<br>• قرارات متأخرة<br>• بيانات غير متسقة</div></div><div class="col-sm-6"><div class="p-3 rounded" style="background: rgba(0, 206, 201, 0.1);"><strong>بعد:</strong><br>• ٣٠ دقيقة/أسبوع للمراقبة<br>• رؤى لحظية<br>• قرارات واثقة</div></div></div></div>'},{q:"كيف تتعامل مع بيانات أعمالنا الحساسة؟",a:'<strong>في مكالمة الاكتشاف، نناقش بياناتك دون الحاجة لتسليم أي شيء.</strong> إذا تقدمنا في المشروع، أعمل داخل بيئة Microsoft الخاصة بك باستخدام الأمان على مستوى الصف (RLS)، والاتصالات المشفرة، والحوكمة على مستوى الشركات.<div class="mt-3"><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>توقيع اتفاقية سرية (NDA) قبل الوصول لأي بيانات</span></div><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>تبقى البيانات داخل حساب Microsoft الخاص بك</span></div><div class="d-flex align-items-start mb-2"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>تطبيق ضوابط الوصول المستندة إلى الأدوار الوظيفية</span></div><div class="d-flex align-items-start"><i class="bi bi-check-circle-fill text-success me-2 mt-1"></i><span>سجل تدقيق كامل لجميع الأنشطة</span></div></div>'},{q:"ماذا لو كانت بياناتنا فوضوية؟ ملفات Excel، أنظمة قديمة، عمليات يدوية؟",a:'<strong>هذا أمر طبيعي، وهو بالضبط نوع المشكلة التي أحلّها.</strong> أربط وأنظّف البيانات من أنظمة CRM ومنصات التجارة الإلكترونية وأنظمة ERP وجداول البيانات في نموذج واحد موثوق.<div class="mt-3 p-3 rounded" style="background: rgba(108, 92, 231, 0.1);"><strong>أتصل بـ:</strong> أنظمة CRM، Shopify، WooCommerce، قواعد بيانات SQL، واجهات APIs، ملفات Excel، ومعظم مصادر بيانات الأعمال الشائعة الأخرى.</div><p class="mt-3 mb-0"><em>"كلما كانت بياناتك أكثر فوضوية، كان تأثير التحول أكبر."</em></p>'},{q:"هل سيتمكن فريقنا من استخدام لوحات التحكم؟",a:'<strong>بالتأكيد. أبني الحلول لتناسب مستوى مهارة فريقك وأقدم تدريبًا شاملاً.</strong> يتضمن كل مشروع تدريبًا للمستخدمين ووثائق كاملة، بالإضافة إلى خيارات دعم مستمرة.<div class="mt-3"><div class="row g-2 small"><div class="col-md-6"><strong class="text-accent">للمستخدمين:</strong><br>• كيفية قراءة لوحات التحكم<br>• الفلترة والتعمق في البيانات<br>• خيارات التصدير والمشاركة</div><div class="col-md-6"><strong class="text-accent">للمسؤولين:</strong><br>• جدولة تحديث البيانات<br>• صلاحيات المستخدمين<br>• استكشاف الأخطاء الأساسية</div></div></div>'},{q:"لماذا العمل مع متخصص مستقل بدلاً من شركة استشارات كبرى؟",a:"<strong>تحصل على وصول مباشر للشخص الذي يبني نموذجك فعليًا.</strong> بلا مدير حسابات ينقل الطلبات إلى محلل مبتدئ. لقد بنيت <a href='dashboards/dataarcus-pulse.html' class='text-accent'>داتا أركوس بلس</a>، نموذج CRM للمبيعات بمستوى الإنتاج، بنفسي بالكامل، وهذا هو مستوى الملكية العملية الذي يحصل عليه كل مشروع.<div class=\"mt-3 p-3 rounded\" style=\"background: rgba(0, 212, 255, 0.1); border: 1px solid var(--accent);\">ما تخسره مقارنة بشركة كبرى هو التكاليف الإضافية. وما تكسبه هو السرعة والتواصل المباشر وشخص مسؤول شخصيًا عن كل رقم في لوحة تحكمك.</div>"},{q:"ماذا لو لم نكن متأكدين مما نحتاجه؟",a:"<strong>هذا بالضبط سبب وجود مكالمة وضوح البيانات المجانية.</strong> أحضر ما لديك، وسأساعدك في تحديد الفرصة الحقيقية، حتى لو لم تكن بناء لوحة تحكم كاملة بعد. لا يوجد أي التزام مطلوب."},{q:"هل يرى وكيل الذكاء الاصطناعي بياناتي؟",a:"<strong>يقرأ بنية نموذجك، لا الصفوف التي فيه.</strong> تعمل أدوات الوكيل على جهازك أنت، في Claude Desktop: تقرأ بنية النموذج (الجداول والأعمدة والمقاييس والتنسيقات)، لا الصفوف التي فيه، وتكتب تقريرًا جديدًا بجانب نموذجك. ويستأذنك Claude Desktop قبل كل ملف يكتبه. المزيد في <a href='/power-bi-mcp/' class='text-accent'>صفحة النسخة التجريبية</a> وفي <a href='https://github.com/Antnioo/DataArcus/blob/main/mcp/PRIVACY.md' class='text-accent' target='_blank' rel='noopener'>PRIVACY.md</a>."}]},finalCta:{title:"هل أنت مستعد لرؤية بياناتك في العمل؟",subtitle:"احجز مكالمة وضوح بيانات مجانية مدتها 20 دقيقة. بدون التزام، فقط نظرة صريحة على ما هو ممكن بما لديك.",button:"احجز مكالمتك المجانية"},contact:{title:"ابدأ محادثة حول بياناتك",subtitle:"أخبرني عن أعمالك والقرارات التي تحتاج بيانات أفضل من أجلها، وسأوضح لك ما هو ممكن في مكالمة مجانية.",form:{name:"الاسم بالكامل *",email:"البريد الإلكتروني للعمل *",company:"الشركة",platform:"مصدر البيانات / المنصة (اختياري)",platformPlaceholder:"مثال: نظام CRM، Shopify، قاعدة بيانات داخلية...",details:"تفاصيل المشروع *",placeholder:"مثال: نستخدم نظام CRM وبعض جداول البيانات. نحتاج رؤية موحدة للعملاء المحتملين والتحويل وأداء الفريق...",button:"احجز مكالمتي المجانية",response:"الرد خلال يوم عمل واحد"},checklist:{title:"ما الذي تحضره إلى مكالمة وضوح البيانات",items:[{title:"قرار واحد تريد اتخاذه أسرع",desc:'مثال: "أي الحملات تجلب مشترين، وليس مجرد عملاء محتملين؟"'},{title:"أين توجد بياناتك اليوم",desc:"تصدير من CRM، أو ملفات Excel، أو متجر Shopify، أو Google Sheets وغيرها"},{title:"من يقرأ الأرقام",desc:"أنت، أحد المدراء، أم فريق المبيعات؟"},{title:"كيف يبدو الأفضل",desc:"تقرير تتوقف عن إعداده يدويًا، أو رقم تثق به أخيرًا"}]},timeline:{title:"كيف يسير المشروع عادةً",items:[{label:"الاكتشاف والوصول إلى البيانات",value:"الأسبوع الأول"},{label:"نموذج البيانات والمقاييس",value:"الأسبوعان الأول والثاني"},{label:"بناء لوحة التحكم",value:"الأسبوعان الثاني والثالث"},{label:"الاختبار والتدريب والتسليم",value:"الأسبوعان الثالث والرابع"}],note:"المهام الأصغر، مثل تقرير واحد على بيانات نظيفة، قد تستغرق أيامًا قليلة. تحصل على جدول زمني محدد بعد المكالمة."}}}};